Store the facts in named variables so the text lives in one place, then print one fact per line.

code:
const name = "JavaScript";
const year = 1995;
const job = "makes web pages react to clicks and data";
console.log("Language:", name);
console.log("Created:", year);
console.log("Job:", job);

output:
Language: JavaScript
Created: 1995
Job: makes web pages react to clicks and data

An object groups related values under keys. Read each key by name when you log it.

code:
const js = {
  name: "JavaScript",
  year: 1995,
  type: "interpreted"
};
console.log(js.name);
console.log(js.year);
console.log(js.type);

output:
JavaScript
1995
interpreted

Join the parts with the + operator so the whole label is built before it is printed.

code:
const name = "JavaScript";
const edition = "ECMAScript";
const year = 2023;
const line = name + " follows the " + edition + " standard, updated in " + year;
console.log(line);

output:
JavaScript follows the ECMAScript standard, updated in 2023

Keep the list in an array and walk it with a while loop that stops at the array length.

code:
const runtimes = ["browser", "Node.js", "Deno", "Bun"];
let i = 0;
while (i < runtimes.length) {
  console.log("runs in:", runtimes[i]);
  i = i + 1;
}

output:
runs in: browser
runs in: Node.js
runs in: Deno
runs in: Bun

Give each layer a one-line job description and print them so the three roles sit side by side.

code:
const html = "HTML gives the page its structure";
const css = "CSS decides how it looks";
const js = "JavaScript decides how it behaves";
console.log(html);
console.log(css);
console.log(js);

output:
HTML gives the page its structure
CSS decides how it looks
JavaScript decides how it behaves

A function bundles the printing logic. Call it after the declaration to see the output.

code:
const name = "JavaScript";
const purpose = "adds behaviour to a page";
const places = ["the browser", "the server"];
function introduce() {
  console.log("I am", name);
  console.log("I", purpose);
  console.log("I run in", places[0], "and", places[1]);
}
introduce();

output:
I am JavaScript
I adds behaviour to a page
I run in the browser and the server

Strings know their own size through the length property, so you never count manually.

code:
const lang = "JavaScript";
console.log("Text:", lang);
console.log("Characters:", lang.length);
console.log("Upper case:", lang.toUpperCase());

output:
Text: JavaScript
Characters: 10
Upper case: JAVASCRIPT

Model the file details as an object, then log each field on its own line.

code:
const meta = {
  filename: "app.js",
  language: "JavaScript",
  runCommand: "node app.js"
};
console.log("file:", meta.filename);
console.log("language:", meta.language);
console.log("run it with:", meta.runCommand);

output:
file: app.js
language: JavaScript
run it with: node app.js

Build the sentence from the flags with +, so the printed line is a single value.

code:
const isInterpreted = true;
const isJIT = true;
const summary = "Interpreted: " + isInterpreted + " | Uses JIT: " + isJIT;
console.log(summary);

output:
Interpreted: true | Uses JIT: true

Keep the reasons in an array and let a counter supply the numbers, so the list grows with the array.

code:
const reasons = ["fast feedback", "big job market", "runs everywhere"];
let n = 1;
for (const reason of reasons) {
  console.log(n + ". " + reason);
  n = n + 1;
}

output:
1. fast feedback
2. big job market
3. runs everywhere

typeof tells you which kind of value you have. Return a readable word from the function and log both calls.

code:
function describe(value) {
  if (typeof value === "number") {
    return "number";
  }
  return "text";
}
console.log(42, "is a", describe(42));
console.log("42", "is a", describe("42"));

output:
42 is a number
42 is a text

These are the classic surprises. typeof gives back a string for every one of them, and two of the answers are wrong on purpose.

code:
console.log(typeof null);
console.log(typeof undefined);
console.log(typeof 0);
console.log(typeof "");
console.log(typeof NaN);
console.log(typeof []);
console.log(typeof {});

output:
object
undefined
number
string
number
object
object

Numbers are stored in binary, so some fractions cannot be written exactly. toFixed rounds for display only.

code:
console.log(0.1 + 0.2);
console.log(1 / 3);
console.log(2 ** 53);
console.log((0.1 + 0.2).toFixed(2));

output:
0.30000000000000004
0.3333333333333333
9007199254740992
0.30

The + operator joins when either side is a string. The arithmetic operators force both sides to numbers instead.

code:
console.log("5" + 3);
console.log("5" - 3);
console.log("5" * "3");
console.log(5 + 3 + "");

output:
53
2
15
8

Loose equality is what makes these strange. An empty array is truthy, so ![] is false, and [] == false compares to 0.

code:
console.log([] == false);
console.log([] == ![]);
console.log([] + {});
console.log(typeof (() => {}));

output:
true
true
[object Object]
function

Function declarations are moved to the top of the scope before anything runs, so the call works. const functions do not get this treatment.

code:
console.log("result:", add(2, 3));
function add(a, b) {
  return a + b;
}
console.log("later call:", add(10, 20));

output:
result: 5
later call: 30

var is function scoped, so every push sees the same final value of i. let is block scoped, so each round keeps its own copy.

code:
var withVar = [];
for (var i = 0; i < 3; i = i + 1) {
  withVar.push(i);
}
let withLet = [];
for (let j = 0; j < 3; j = j + 1) {
  withLet.push(j);
}
console.log(withVar);
console.log(withLet);

output:
[ 0, 1, 2 ]
[ 0, 1, 2 ]

JavaScript runs top to bottom and waits for each statement to finish, so the order is exactly the order you wrote.

code:
function first() {
  return "first";
}
function second() {
  return "second";
}
console.log(1, first());
console.log(2, second());

output:
1 first
2 second

A const binding cannot be reassigned, so JavaScript throws a TypeError. Catching it lets the script keep running.

code:
const value = 10;
try {
  value = 99;
} catch (err) {
  console.log(err.name);
  console.log(err.message);
}
console.log("value is still", value);

output:
TypeError
Assignment to constant variable.
value is still 10

const has a temporal dead zone: it exists but cannot be read yet. Reading it throws a ReferenceError.

code:
try {
  console.log(later);
  const later = "I am declared below";
} catch (err) {
  console.log(err.name);
  console.log(err.message);
}

output:
ReferenceError
Cannot access 'later' before initialization

NaN is the only value that is not equal to itself. Loose == converts types, strict === does not, and null only loosely matches undefined.

code:
console.log(NaN === NaN);
console.log(Object.is(NaN, NaN));
console.log(1 == "1");
console.log(1 === "1");
console.log(null == undefined);
console.log(null === undefined);

output:
false
true
true
false
true
false

Primitives are the simple values. Compare typeof results to check the type and exclude the null trap.

code:
function isPrimitive(value) {
  const t = typeof value;
  if (t === "object" && value === null) {
    return false;
  }
  return t !== "object" && t !== "function";
}
console.log(42, isPrimitive(42));
console.log("hi", isPrimitive("hi"));
console.log([], isPrimitive([]));
console.log(null, isPrimitive(null));

output:
42 true
hi true
[] false
null false

Compare the key lists first, then the values for each key. Loop over the keys of the first object.

code:
function deepEqual(a, b) {
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) {
    return false;
  }
  for (const key of keysA) {
    if (a[key] !== b[key]) {
      return false;
    }
  }
  return true;
}
console.log(deepEqual({ a: 1, b: 2 }, { a: 1, b: 2 }));
console.log(deepEqual({ a: 1, b: 2 }, { a: 1, b: 3 }));

output:
true
false

Math.round goes to the nearest number, Math.floor always drops the decimal. Dividing two integers still gives a fraction in JavaScript.

code:
console.log(Math.max(1, 2, 3));
console.log(Math.min());
console.log(Math.round(4.6));
console.log(Math.floor(4.9));
console.log(7 / 2);
console.log(Math.floor(7 / 2));

output:
3
Infinity
5
4
3.5
3

Turn the string into an array, flip the array order and join it back into a string.

code:
function reverse(text) {
  return text.split("").reverse().join("");
}
const word = "JavaScript";
console.log(reverse(word));
console.log(reverse(word) === "tpircSavaJ");

output:
tpircSavaJ
true

Split the sentence on spaces and read the length of the resulting array.

code:
function countWords(sentence) {
  return sentence.split(" ").length;
}
const sentence = "Tests are the cheapest bug catcher we have";
console.log(sentence);
console.log("words:", countWords(sentence));

output:
Tests are the cheapest bug catcher we have
words: 8

Split into words, upper-case the first character of each, then join the words back together.

code:
function toTitleCase(text) {
  return text
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}
console.log(toTitleCase("javascript test automation"));

output:
Javascript Test Automation

push appends to the end of the array and returns the new length, which is why the count changes.

code:
const scores = [];
console.log("at start:", scores.length);
scores.push(10);
scores.push(20);
scores.push(30);
console.log("after push:", scores.length);
console.log(scores.join(", "));

output:
at start: 0
after push: 3
10, 20, 30

The plus operator glues values into text instead of merging them. Spread inside array brackets builds a real new array.

code:
console.log([1, 2, 3] + [4, 5, 6]);
console.log({ a: 1 } + { a: 1 });
const merged = [...[1, 2, 3], ...[4, 5, 6]];
console.log(merged);

output:
1,2,34,5,6
[object Object][object Object]
[ 1, 2, 3, 4, 5, 6 ]

Strings are the one value that gets glued instead of added, and you can build an object with either key style.

code:
console.log("total: " + 5 + ",");
console.log("5".repeat(3));
const key = "browser";
const runtime = { name: "Node.js" };
runtime[key] = "yes";
console.log(runtime.name, "runs in browser:", runtime.browser);

output:
total: 5,
555
Node.js runs in browser: yes

typeof covers everything in the language. Functions and classes both report as function, and globalThis exists in every JavaScript environment.

code:
console.log(typeof globalThis);
console.log(typeof function () {});
console.log(typeof class Example {});
console.log(globalThis === this || typeof globalThis === "object");

output:
object
function
function
true

The string "false" is not empty, so it is truthy. Number turns text into a real number, which is what the addition needs.

code:
console.log("1+2".split("+"));
console.log(Boolean("false"));
console.log(Number("42") + 1);
console.log(Number("abc") + 1);

output:
[ '1', '2' ]
true
43
NaN

|| and && work on truthiness, so 0 and empty string count as falsy. ?? only falls back on null and undefined, so 0 survives.

code:
console.log("0 || default =", 0 || "default");
console.log("empty && kept =", JSON.stringify("" && "kept"));
console.log("null ?? fallback =", null ?? "fallback");
console.log("5 ?? 9 =", 5 ?? 9);
console.log("0 ?? 9 =", 0 ?? 9);

output:
0 || default = default
empty && kept = ""
null ?? fallback = fallback
5 ?? 9 = 5
0 ?? 9 = 0

Strings behave a lot like arrays for indexing and slicing. A negative index counts back from the end.

code:
const word = "JavaScript";
console.log(word.length);
console.log(word.at(-1));
console.log(word.slice(0, 4));
console.log(word.slice(4, -1));

output:
10
t
Java
Scrip

A comparison returns a boolean, and that boolean is then compared as a number in the next step, which breaks the chain.

code:
console.log(1 < 2 < 3);
console.log(3 > 2 > 1);
console.log("5" == 5);
console.log("5" === 5);

output:
true
false
true
false
